#include <stdio.h>
#include "pico/stdlib.h"
#include "pico/multicore.h"
#include "pico/time.h"
#include "hardware/pio.h"
#include "hardware/clocks.h"    // for set_sys_clock_khz(250000, true)
#include "hardware/vreg.h"
#include "hardware/sync.h"
#include "hardware/structs/sio.h"
#include "Address.pio.h"        // Generated by pioasm
#include "serial.pio.h"         // Generated by pioasm
#include "sram.h"

#define SYS_CLOCK_KHZ 250000
#define SYS_CLOCK_VOLTAGE VREG_VOLTAGE_1_20
#define SERIAL_PIN 26
#define SERIAL_BAUD 115200

#include "hardware/watchdog.h"

void software_reset()
{
    watchdog_enable(1, 1);
    while(1); 
}

void __not_in_flash_func(core1_entry)()
{
    PIO serial_pio = pio1;
    uint serial_offset = pio_add_program(serial_pio, &serial_program);
    uint serial_rx_offset = pio_add_program(serial_pio, &serial_rx_program);
    uint serial_sm = pio_claim_unused_sm(serial_pio, true);
    uint serial_rx_sm = pio_claim_unused_sm(serial_pio, true);
    serial_program_init(serial_pio, serial_sm, serial_offset, SERIAL_PIN, SERIAL_BAUD);
    serial_rx_program_init(serial_pio, serial_rx_sm, serial_rx_offset, SERIAL_PIN, SERIAL_BAUD);
    serial_program_set_tx_mode(serial_pio, serial_sm, serial_rx_sm, SERIAL_PIN);

    gpio_put(PICO_DEFAULT_LED_PIN, 1);
    busy_wait_ms(500);

    serial_program_puts(serial_pio, serial_sm, "\033[2J\033[H*** RP 6502 Terminal ***\r\n");
    serial_program_puts(serial_pio, serial_sm, "READY\r\n");
    serial_program_wait_tx_done(serial_pio, serial_sm, SERIAL_BAUD);
    serial_program_set_rx_mode(serial_pio, serial_sm, serial_rx_sm, SERIAL_PIN);

    volatile uint8_t *light = &sram[0x1c00];    // light points ta memory location voliatile makes sure it passes between cores
    char command_text[80];
    size_t command_len = 0;
    while (true)
    {
        int command = serial_rx_program_getc_timeout_us(serial_pio, serial_rx_sm, 1000);
        if (command < 0)
        {
            tight_loop_contents();
            continue;
        }

        if (command != '\r' && command != '\n')
        {
            if (command_len + 1 < sizeof(command_text))
            {
                command_text[command_len++] = (char)command;
            }
            continue;
        }

        if (command_text[0]=='R' && command_len==1) software_reset();

        command_len = 0;
        gpio_xor_mask(1u << PICO_DEFAULT_LED_PIN);

        char serial_text[6];
        snprintf(serial_text, sizeof(serial_text), "%u\r\n", *light);

        serial_program_set_tx_mode(serial_pio, serial_sm, serial_rx_sm, SERIAL_PIN);
        serial_program_puts(serial_pio, serial_sm, serial_text);
        serial_program_wait_tx_done(serial_pio, serial_sm, SERIAL_BAUD);
        serial_program_set_rx_mode(serial_pio, serial_sm, serial_rx_sm, SERIAL_PIN);
    }
}

int __not_in_flash_func(main)()
{
    // 1. Increase clock speed to provide more overhead for the bus loop
    vreg_set_voltage(SYS_CLOCK_VOLTAGE);
    busy_wait_ms(2);
    set_sys_clock_khz(SYS_CLOCK_KHZ, true);

    gpio_init(PICO_DEFAULT_LED_PIN);
    gpio_set_dir(PICO_DEFAULT_LED_PIN, GPIO_OUT);
    gpio_put(PICO_DEFAULT_LED_PIN, 0);
    busy_wait_ms(500);

    multicore_launch_core1(core1_entry);

    /* Initialize Data Bus (GPIO 0-7) for software (SIO) control */
    for (int i = 0; i < 8; i++)
    {
        gpio_init(i);
        gpio_set_dir(i, GPIO_IN);
      
        gpio_set_drive_strength(i, GPIO_DRIVE_STRENGTH_12MA);
        gpio_set_slew_rate(i, GPIO_SLEW_RATE_FAST);
    }

    /* Address bus GPIO 8-22, R/W GPIO 27, Clock GPIO 28 */
    PIO pio = pio0;                                     // select one of two pios
    uint address_offset = pio_add_program(pio, &Address_program); // Load program
    uint sm = pio_claim_unused_sm(pio, true);           // Claim a state machine
    Address_program_init(pio, sm, address_offset, 8, 27, 28);

    // Optimized pointers and masks for the tight loop
    const volatile uint32_t *pio_fifo = &pio->rxf[sm];
    const uint32_t data_mask = 0xFF;
    const uint32_t clock_pin_mask = (1u << 28);
    const uint32_t rw_mask = (1u << 27);

    // Start the address sampler from a known-empty FIFO.
    pio_sm_set_enabled(pio, sm, false);
    pio_sm_clear_fifos(pio, sm);
    pio_sm_restart(pio, sm);
    pio_sm_set_enabled(pio, sm, true);

    // stdio_init_all();   // Initialize stdio (USB and UART if available)
    uint32_t ints = save_and_disable_interrupts();
    (void)ints;

    while (true)
    {
        // Wait for a new address sample from the PIO
        while (pio_sm_is_rx_fifo_empty(pio, sm));

        uint32_t address_raw = *pio_fifo;
        uint32_t address = (address_raw >> 8) & 0x7FFF; // GPIO 8-22 are A0-A14

        if (address_raw & rw_mask)                    // GPIO 27 = R/W
        {
            // Read Cycle: SRAM -> Bus
            uint32_t data = sram[address];

            // Direct SIO writes are faster and more deterministic than the SDK
            // GPIO helpers in this timing-critical bus window.
            sio_hw->gpio_clr = data_mask;
            sio_hw->gpio_set = data;
            sio_hw->gpio_oe_set = data_mask;
            
            // Wait for Clock (GPIO 28) to go low (end of cycle)
            while (sio_hw->gpio_in & clock_pin_mask);
            
            sio_hw->gpio_oe_clr = data_mask;

            // The PIO emits a second word every cycle: the last data sample
            // taken while PHI2 was high. Reads do not use it, but consuming it
            // keeps the FIFO stream aligned on the next address sample.
            while (pio_sm_is_rx_fifo_empty(pio, sm));
            (void)*pio_fifo;
//            printf("Read: %02X address: %04X\n",sram[address],address);
        }
        else
        {
            // Write Cycle: Bus -> SRAM
            // Use the last data sample captured by PIO while PHI2 was high.
            while (pio_sm_is_rx_fifo_empty(pio, sm));
            uint32_t data_raw = *pio_fifo;
            sram[address] = (uint8_t)(data_raw & data_mask);
//            printf("Write: %02X address: %04X\n", sram[address], address);
        }
    }
}
